'use strict';

// MODULES //

var tape = require( 'tape' );
var isSameFloat32Array = require( '@stdlib/assert/is-same-float32array' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var Float32Array = require( '@stdlib/array/float32' );
var cexpf = require( './../lib/assign.js' );


// FIXTURES //

var pureImaginary = require( './fixtures/julia/pure_imaginary.json' );
var generalComplex = require( './fixtures/julia/general_complex.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cexpf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function evaluates the complex exponential', function test( t ) {
	var expected;
	var out;
	var v;

	out = new Float32Array( 2 );
	v = cexpf( 0.0, 0.0, out, 1, 0 );

	expected = new Float32Array( [ 1.0, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 4 );
	v = cexpf( 0.0, 0.0, out, 2, 0 );

	expected = new Float32Array( [ 1.0, 0.0, 0.0, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 4 );
	v = cexpf( 0.0, 0.0, out, 2, 1 );

	expected = new Float32Array( [ 0.0, 1.0, 0.0, 0.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	out = new Float32Array( 4 );
	v = cexpf( 0.0, 0.0, out, -2, 3 );

	expected = new Float32Array( [ 0.0, 0.0, 0.0, 1.0 ] );

	t.strictEqual( v, out, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );

	t.end();
});

tape( 'the function computes exp(z) for pure imaginary z', function test( t ) {
	var expected;
	var expre;
	var expim;
	var out;
	var re;
	var im;
	var i;

	re = pureImaginary.re;
	im = pureImaginary.im;
	expre = pureImaginary.expre;
	expim = pureImaginary.expim;

	out = new Float32Array( 2 );

	for ( i = 0; i < re.length; i++ ) {
		cexpf( f32( re[ i ] ), f32( im[ i ] ), out, 1, 0 );
		expected = new Float32Array( [ expre[ i ], expim[ i ] ] );
		t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function computes exp(z) for complex z', function test( t ) {
	var expre;
	var expim;
	var out;
	var re;
	var im;
	var i;

	re = generalComplex.re;
	im = generalComplex.im;
	expre = generalComplex.expre;
	expim = generalComplex.expim;

	out = new Float32Array( 2 );

	for ( i = 0; i < re.length; i++ ) {
		cexpf( f32( re[ i ] ), f32( im[ i ] ), out, 1, 0 );
		t.strictEqual( isAlmostSameValuef( out[ 0 ], f32( expre[ i ] ), 2 ), true, 'returns expected value' );
		t.strictEqual( isAlmostSameValuef( out[ 1 ], f32( expim[ i ] ), 2 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'if imaginary component is `+Infinity`, the function returns `NaN` components', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( 0.0, PINF, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if imaginary component is `-Infinity`, the function returns `NaN` components', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( 0.0, NINF, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `-Infinity`, the function returns both components equal to `0`', function test( t ) {
	var expected;
	var out;

	out = new Float32Array( 2 );
	cexpf( NINF, 1.0, out, 1, 0 );

	expected = new Float32Array( [ 0.0, 0.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `+Infinity` and imaginary component is `0.0`, the function returns `+Infinity` and `0.0`', function test( t ) {
	var expected;
	var out;

	out = new Float32Array( 2 );
	cexpf( PINF, 0.0, out, 1, 0 );

	expected = new Float32Array( [ PINF, 0.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `NaN` and imaginary component is `0.0`, the function returns `NaN` and `0.0`', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( NaN, 0.0, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( out[ 1 ], 0.0, 'returns expected value' );
	t.end();
});

tape( 'if imaginary component is `NaN`, the function returns `NaN` components', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( 5.0, NaN, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );

	cexpf( 0.0, NaN, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );

	cexpf( NaN, NaN, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );

	t.end();
});

tape( 'if imaginary component is `+0.0`, the function returns an imaginary component equal to `+0.0`', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( 3.0, 0.0, out, 1, 0 );
	t.strictEqual( isPositiveZerof( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if imaginary component is `-0.0`, the function returns an imaginary component equal to `-0.0`', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( 3.0, -0.0, out, 1, 0 );
	t.strictEqual( isNegativeZerof( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `NaN` and imaginary component is nonzero, the function returns `NaN` components', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( NaN, 3.0, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `NaN` and imaginary component is `+0.0`, the function returns an imaginary component equal to `+0.0`', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( NaN, 0.0, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `NaN` and imaginary component is `-0.0`, the function returns an imaginary component equal to `-0.0`', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( NaN, -0.0, out, 1, 0 );
	t.strictEqual( isnanf( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isNegativeZerof( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `+Infinity` and imaginary component is `+Infinity`, the function returns `-Infinity` and `NaN`', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( PINF, PINF, out, 1, 0 );
	t.strictEqual( out[ 0 ], NINF, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `-Infinity` and imaginary component is `+Infinity`, the function returns `-0.0` and `+0.0`', function test( t ) {
	var expected;
	var out;

	out = new Float32Array( 2 );
	cexpf( NINF, PINF, out, 1, 0 );

	expected = new Float32Array( [ -0.0, 0.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `-Infinity` and imaginary component is `-Infinity`, the function returns `-0.0` and `-0.0`', function test( t ) {
	var expected;
	var out;

	out = new Float32Array( 2 );
	cexpf( NINF, NINF, out, 1, 0 );

	expected = new Float32Array( [ -0.0, -0.0 ] );

	t.strictEqual( isSameFloat32Array( out, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes exp(z) for pure real z (positive)', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( 1.0, 0.0, out, 1, 0 );
	t.strictEqual( out[ 0 ], 2.7182817459106445, 'returns expected value' );
	t.strictEqual( isPositiveZerof( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'the function computes exp(z) for pure real z (negative)', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( -1.0, 0.0, out, 1, 0 );
	t.strictEqual( out[ 0 ], 0.3678794503211975, 'returns expected value' );
	t.strictEqual( isPositiveZerof( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is a large positive value and imaginary component is `0.0`, the function returns `+Infinity`', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( 89.0, 0.0, out, 1, 0 );
	t.strictEqual( out[ 0 ], PINF, 'returns expected value' );
	t.strictEqual( isPositiveZerof( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `+Infinity` and imaginary component is finite and nonzero, the function returns infinite components', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( PINF, 1.0, out, 1, 0 );
	t.strictEqual( out[ 0 ], PINF, 'returns expected value' );
	t.strictEqual( out[ 1 ], PINF, 'returns expected value' );
	t.end();
});

tape( 'if real component is `-Infinity` and imaginary component is `0.0`, the function returns both components equal to `+0.0`', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( NINF, 0.0, out, 1, 0 );
	t.strictEqual( isPositiveZerof( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if real component is `+Infinity` and imaginary component is `-Infinity`, the function returns `-Infinity` and `NaN`', function test( t ) {
	var out = new Float32Array( 2 );

	cexpf( PINF, NINF, out, 1, 0 );
	t.strictEqual( out[ 0 ], NINF, 'returns expected value' );
	t.strictEqual( isnanf( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});
